import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Entender rankings y competiciones","description":"","frontmatter":{"title":"Entender rankings y competiciones","docId":"user.points.rankings","translationKey":"user.points.rankings","locale":"es","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"1c45cf6e9355092d95dc9f90025b2965e0a6a4cddb453fb25680192ab41e873c","translationRevision":"ef1de0d2b918562f925dae4aed9094a146d2c1c8d657f0c168902a87d2031fa4","order":30},"headers":[],"relativePath":"es/user/points/rankings.md","filePath":"es/user/points/rankings.md","lastUpdated":1795731074000}`),s={name:`es/user/points/rankings.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="understand-rankings-and-competitions" tabindex="-1">Entender rankings y competiciones <a class="header-anchor" href="#understand-rankings-and-competitions" aria-label="Permalink to “Entender rankings y competiciones”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo y requisitos”">​</a></h2><p>Elige la clasificación adecuada y reconoce los límites del espacio de rankings en desarrollo. Necesitas actividad entrante para obtener puntuaciones útiles. Comienza con la tabla habitual de <a href="./rules.html">Points</a> o los paneles de espectadores destacados del <a href="./../live/feed.html">feed LIVE</a> si solo deseas consultar participantes actuales.</p><h2 id="use-the-right-view" tabindex="-1">Elegir la vista <a class="header-anchor" href="#use-the-right-view" aria-label="Permalink to “Elegir la vista”">​</a></h2><ol><li>En <strong>Points</strong>, busca un espectador y ordena por puntos, nivel o identidad. Actualiza antes de comparar un ajuste manual con una asignación.</li><li>En <strong>Live feed</strong>, revisa los paneles de espectadores clasificados disponibles. Pueden recibir instantáneas del motor de rankings independientemente de la tabla de saldos.</li><li>Para una superposición, abre <a href="./../overlays/">Overlays</a>, selecciona el tipo de ranking y revisa sus fuentes. La fuente configurada debe existir para que aparezcan resultados.</li></ol><p>El espacio dedicado <strong>Rankings &amp; competitions</strong> es experimental. Su ruta de frontend es <code>#/rankings</code>, pero está oculto deliberadamente en la navegación principal y no se recupera como pestaña de inicio. La ausencia en la barra lateral no significa que se hayan eliminado la ruta o el motor.</p><h2 id="configure-an-experimental-ranking" tabindex="-1">Configurar un ranking experimental <a class="header-anchor" href="#configure-an-experimental-ranking" aria-label="Permalink to “Configurar un ranking experimental”">​</a></h2><p>Si tu entorno permite acceder a ese espacio, comienza con un creador, una sala, agrupación por usuario y una ventana de sesión. Añade una métrica anunciada, como <code>tiktok.like</code> / <code>like.count</code>, con peso <code>1</code>. Establece un límite de resultados moderado y crea la definición. El formulario también admite ventanas móviles y diarias, con límites de duración y eventos o un desplazamiento horario explícito.</p><p>Lee la instantánea resultante antes de añadir fuentes. Pausar y reanudar afectan a la recopilación; reiniciar borra intencionalmente el estado del ranking. Las opciones de competición y las fuentes de votos tienen restricciones de agrupación propias. No supongas que reiniciar puntos reinicia una competición ni que toda agrupación personalizada admite cualquier métrica.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado y estado”">​</a></h2><p>Las tablas habituales están disponibles; la administración dedicada sigue siendo experimental. Las puntuaciones provienen del host, no de contar filas visibles. Esta guía no acredita aceptación real en emisión/OBS ni todas las combinaciones de competición.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperación”">​</a></h2><p>Si no hay puntuaciones, revisa creador, sala, fuente activa, ventana y pausa. Retira combinaciones incompatibles en lugar de inventar campos. Conserva datos mediante <a href="./../preferences/backups.html">copias de seguridad</a> antes de reiniciar e incluye el ID de definición y el código de diagnóstico al informar de un fallo.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalles de operación”">​</a></h2><p>La tabla de Points solicita 100 espectadores y filtra/ordena solo las filas recibidas. Refrescar u ordenar por nombre no consulta toda la base. Los rankings del feed muestran 10 filas por sesión de creador/sala: diamantes de regalos en Top y cantidades en Likes, con seguimiento limitado a 5.000 espectadores. No representan puntos guardados. Compara unidades y límites de sesión antes de comparar totales.</p><p>Pruébalo interactivamente antes de tocar tu configuración real:</p>`,16),t(d,{scenario:`points`,locale:`es`,panel:`points`,title:`Prueba rankings y puntos de espectadores`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Operaciones de línea de comandos <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operaciones de línea de comandos”">​</a></h2><p>Cada operación de esta guía también está disponible desde la CLI: sin conexión, scriptable y apta para agentes. Las líneas de uso son sintaxis del parser y permanecen en inglés en todos los idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools ranking list</code></td><td>listar las definiciones de ranking</td></tr><tr><td><code>tiktools ranking metrics</code></td><td>métricas disponibles para las definiciones de ranking</td></tr><tr><td><code>tiktools ranking create --record &lt;json&amp;#124;@file&gt;</code></td><td>crear una definición de ranking</td></tr><tr><td><code>tiktools ranking update --record &lt;json&amp;#124;@file&gt;</code></td><td>actualizar una definición de ranking</td></tr><tr><td><code>tiktools ranking get &lt;id&gt;</code></td><td>leer un ranking</td></tr><tr><td><code>tiktools ranking snapshot &lt;id&gt;</code></td><td>clasificación actual de un ranking</td></tr><tr><td><code>tiktools ranking delete &lt;id&gt;</code></td><td>eliminar un ranking <strong>destructivo</strong></td></tr><tr><td><code>tiktools ranking reset &lt;id&gt;</code></td><td>restablecer el estado acumulado <strong>destructivo</strong></td></tr><tr><td><code>tiktools ranking pause &lt;id&gt;</code></td><td>pausar la acumulación</td></tr><tr><td><code>tiktools ranking resume &lt;id&gt;</code></td><td>reanudar la acumulación</td></tr><tr><td><code>tiktools ranking contribute --record &lt;json&amp;#124;@file&gt;</code></td><td>añadir una contribución externa</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools competition list</code></td><td>listar las competiciones</td></tr><tr><td><code>tiktools competition get &lt;id&gt;</code></td><td>leer una competición</td></tr><tr><td><code>tiktools competition create --record &lt;json&amp;#124;@file&gt;</code></td><td>crear una competición</td></tr><tr><td><code>tiktools competition update --record &lt;json&amp;#124;@file&gt;</code></td><td>actualizar una competición</td></tr><tr><td><code>tiktools competition delete &lt;id&gt;</code></td><td>eliminar una competición <strong>destructivo</strong></td></tr><tr><td><code>tiktools competition state &lt;id&gt;</code></td><td>estado actual de la competición</td></tr><tr><td><code>tiktools competition results &lt;id&gt;</code></td><td>resultados finales o intermedios</td></tr><tr><td><code>tiktools competition action --record &lt;json&amp;#124;@file&gt;</code></td><td>registrar una acción de competición</td></tr><tr><td><code>tiktools competition mark-action-uncertain --record &lt;json&amp;#124;@file&gt;</code></td><td>marcar una acción como incierta</td></tr><tr><td><code>tiktools competition resolve-action --record &lt;json&amp;#124;@file&gt;</code></td><td>resolver una acción incierta</td></tr><tr><td><code>tiktools competition start &lt;id&gt;</code></td><td>iniciar una competición</td></tr><tr><td><code>tiktools competition finish &lt;id&gt;</code></td><td>finalizar una competición <strong>destructivo</strong></td></tr><tr><td><code>tiktools competition candidates &lt;id&gt;</code></td><td>candidatos a ganador</td></tr><tr><td><code>tiktools competition select-winner --record &lt;json&amp;#124;@file&gt;</code></td><td>seleccionar el ganador</td></tr><tr><td><code>tiktools competition pause &lt;id&gt;</code></td><td>pausar una competición</td></tr><tr><td><code>tiktools competition resume &lt;id&gt;</code></td><td>reanudar una competición</td></tr><tr><td><code>tiktools competition cancel &lt;id&gt;</code></td><td>cancelar una competición <strong>destructivo</strong></td></tr></tbody></table><p>Consulta la <a href="./../../developer/cli.html">referencia completa de comandos</a> para las convenciones, la salida JSON y los marcadores de operaciones destructivas.</p>`,5)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};